/**
 * NEXORA MD - Web Session Loader
 * Loads a Baileys session from a session ID generated by the web pairing portal.
 *
 * Session format:
 *   Short:  Nexora~abc123xyz        → fetched from sessionServerUrl
 *   Long:   Nexora~H4sIAAAAA...     → base64(zlib(creds.json)) inline
 */

const fs = require('fs');
const zlib = require('zlib');
const path = require('path');
const axios = require('axios');
const settings = require('../settings');

const sessionDir = path.join(__dirname, '..', 'data', 'session');
const credsPath = path.join(sessionDir, 'creds.json');

// ─────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────
function ensureSessionDir() {
  if (!fs.existsSync(sessionDir)) {
    fs.mkdirSync(sessionDir, { recursive: true });
  }
}

function isPlaceholder(id) {
  if (!id || typeof id !== 'string') return true;
  const trimmed = id.trim();
  if (trimmed === '') return true;
  if (trimmed === 'PASTE_YOUR_SESSION_ID_HERE') return true;
  return false;
}

/**
 * Load a Baileys session from a session ID.
 * Returns:
 *   true  → session loaded, creds.json is ready
 *   false → no session to load (fall back to QR/pair-code flow)
 */
async function loadSession() {
  const SESSION_ID = settings.sessionId;

  // ─── No session configured → fall back to console pairing ───
  if (isPlaceholder(SESSION_ID)) {
    console.log('[SESSION] No session ID set — falling back to console pairing');
    return false;
  }

  if (typeof SESSION_ID !== 'string') {
    console.log('[SESSION] sessionId must be a string — falling back');
    return false;
  }

  const PREFIX = settings.sessionPrefix || 'Nexora~';

  if (!SESSION_ID.startsWith(PREFIX)) {
    console.log(`[SESSION] Invalid prefix. Expected to start with "${PREFIX}" — falling back`);
    return false;
  }

  ensureSessionDir();

  // Remove any existing creds so we start clean
  if (fs.existsSync(credsPath)) {
    try { fs.unlinkSync(credsPath); } catch (e) {}
  }

  const payload = SESSION_ID.slice(PREFIX.length).trim();

  try {
    // ─── SHORT session → fetch from server ───
    if (payload.length < 50) {
      const serverBase = (settings.sessionServerUrl || '').replace(/\/+$/, '');
      if (!serverBase || serverBase.includes('your-render-url')) {
        console.log('[SESSION] Short session requested but no valid sessionServerUrl configured');
        return false;
      }

      const fetchUrl = `${serverBase}/session/${payload}`;
      console.log(`[SESSION] Fetching short session from ${fetchUrl}`);

      const res = await axios.get(fetchUrl, { timeout: 15000 });
      const fullSession = String(res.data || '').trim();

      if (!fullSession) {
        console.log('[SESSION] Server returned empty session');
        return false;
      }

      // Server returns a full long session string — recurse with it
      return await loadSessionFromString(fullSession);
    }

    // ─── LONG session → decode inline ───
    return await loadSessionFromString(SESSION_ID);
  } catch (e) {
    console.log('[SESSION] Load failed:', e.message);
    return false;
  }
}

/**
 * Internal: decode a full long-format session string
 * (Nexora~BASE64_ZLIB_CREDS)
 */
async function loadSessionFromString(fullSession) {
  const PREFIX = settings.sessionPrefix || 'Nexora~';

  if (!fullSession.startsWith(PREFIX)) {
    throw new Error('Invalid full session format (missing prefix)');
  }

  const payload = fullSession.slice(PREFIX.length).trim();

  const compressedData = Buffer.from(payload, 'base64');
  const decompressedData = zlib.gunzipSync(compressedData);

  // Sanity check — must be valid JSON
  const parsed = JSON.parse(decompressedData.toString('utf8'));
  if (!parsed || !parsed.me) {
    throw new Error('Decoded session is missing expected "me" field');
  }

  fs.writeFileSync(credsPath, decompressedData, 'utf8');
  console.log('[SESSION] ✅ Session loaded successfully from web portal');
  return true;
}

module.exports = { loadSession };